#include "slot_checkpoint_file.cuh"
#include "dual_state_initialization.hpp"
#include <cstdio>
int main(){try{using namespace tao::dual;using namespace tao::data;std::vector<std::vector<Token>>docs;for(int i=0;i<4;++i)docs.push_back(encode({{false,"question"},{true,"answer continuation"}}));Config c;c.layers=1;c.d=4;c.s=2;c.m=3;c.e=8;c.vocab=261;auto init=initialize(c,713);SortedGpuTrainer a(init),b(init);SequenceSlots sa(a,2),sb(b,2);PilotCursor ca(docs,2),cb(docs,2);auto advance=[](SequenceSlots&s,PilotCursor&d){size_t n=0;for(int r=0;r<2;++r)for(size_t k=0;k<2;++k){Work w;if(!d.take(k,8,w))continue;s.begin(k,w.reset);size_t local=0;for(size_t i=w.begin;i<w.end;++i){auto&t=d.docs[w.doc];auto y=s.trainer.graph.step(t[i-1].id);seed_loss(y,t[i].id,t[i].loss);local+=t[i].loss;}s.finish(local!=0);n+=local;}s.trainer.update(n);};advance(sa,ca);auto checkpoint=capture(sa,ca);auto id=checkpoint_identity(c,std::string(64,'a'),std::string(64,'b'),100);save_slot_file(checkpoint,"build/slot_disk_v1.scp",id);auto disk=load_slot_file("build/slot_disk_v1.scp",id,capture(sb,cb),cb);restore(disk,sb,cb);advance(sa,ca);advance(sb,cb);auto x=capture(sa,ca),y=capture(sb,cb);if(x.w!=y.w||x.m!=y.m||x.v!=y.v||x.s!=y.s||x.mem!=y.mem||x.next!=y.next||x.steps!=y.steps)throw std::runtime_error("resume mismatch");for(size_t i=0;i<x.cursor.size();++i)if(x.cursor[i].doc!=y.cursor[i].doc||x.cursor[i].target!=y.cursor[i].target)throw std::runtime_error("cursor mismatch");printf("PASS disk multislot checkpoint exact continuation steps=%u nextdoc=%zu\n",x.steps,x.next);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
